/**
 * TEST-ONLY mock of @minecraft/server-ui.
 *
 * Added Project Prompt 21 to unlock testing ui/BuildMenu.js directly — the
 * one gap flagged as "not covered" in every session's tests/README.md since
 * Project Prompt 18 (`integration.test.mjs` has always substituted a
 * scripted stub for the whole BuildMenu class instead, specifically because
 * this mock didn't exist yet). Mirrors node_modules/@minecraft/server's own
 * mock in spirit: shape-only, just enough of the real
 * ActionFormData/ModalFormData/MessageFormData surface for BuildMenu.js's
 * own logic to run against in plain Node, not a general-purpose UI simulator.
 *
 * NEVER bundled into the shipped .mcaddon — only `BP/`/`RP/` are packaged;
 * this lives at the repository root's `node_modules/`, which the addon
 * packaging step never touches. See tests/README.md.
 *
 * HOW A TEST SCRIPTS A RESPONSE
 *   Real forms are asynchronous and driven by a live player tapping the
 *   screen — nothing this harness can reproduce. Instead, a test calls
 *   `queueFormResponse(player, response)` before triggering the code under
 *   test; the next `.show(player)` call for that exact player object shifts
 *   one queued response off that player's own FIFO queue. Queues are keyed
 *   per player object (a Map), so two players' scripted flows never
 *   interfere with each other — this is deliberate: Project Prompt 21's
 *   multiplayer requirement ("UI state must remain player-specific") is
 *   exactly what a shared/global queue would fail to catch.
 *
 * WHY show() VALIDATES SLIDER BOUNDS ITSELF
 *   A real ModalFormData slider is a physical control — the client cannot
 *   produce a value outside [min, max] or off the valueStep grid; there is
 *   no "submit an invalid slider value" code path on a real device. This
 *   mock enforces the same constraint at `.show()` time (throwing if a
 *   scripted response's formValues entry is out of range or off-step) so a
 *   test attempting to prove "the UI makes 0 or 21 impossible to select" by
 *   scripting an out-of-range response gets a thrown error — the same
 *   structural impossibility a real device would present, not a silent
 *   pass-through that would give a false sense of safety.
 *
 * WHAT'S DELIBERATELY NOT HERE
 *   No icon rendering, no real screen layout, no timing/frame behavior — see
 *   this project's `ui/BuildMenu.js` header for the specific open questions
 *   (icon texture paths, `.body()`'s `{translate, with}` support) this mock
 *   cannot resolve either, because they depend on the real client.
 */

const responseQueues = new Map();

/**
 * @param {object} player
 * @param {object} response e.g. {canceled: false, selection: 1} or
 *   {canceled: false, formValues: [3, 20]} or {canceled: true, cancelationReason: "UserClosed"}.
 */
export function queueFormResponse(player, response) {
  if (!responseQueues.has(player)) {
    responseQueues.set(player, []);
  }
  responseQueues.get(player).push(response);
}

/** Test-teardown helper — clears every player's queued responses. */
export function resetFormResponses() {
  responseQueues.clear();
}

function takeResponse(player, formKind) {
  const queue = responseQueues.get(player);
  if (!queue || queue.length === 0) {
    throw new Error(
      `[server-ui mock] No scripted response queued for ${player?.name ?? "unknown player"}'s ${formKind} screen — call queueFormResponse() first.`
    );
  }
  return queue.shift();
}

function cloneResponse(raw) {
  if (raw.canceled) {
    return { canceled: true, cancelationReason: raw.cancelationReason ?? "UserClosed" };
  }
  return { canceled: false, selection: raw.selection, formValues: raw.formValues };
}

export class ActionFormData {
  constructor() {
    this._title = undefined;
    this._body = undefined;
    this.buttons = [];
  }

  title(message) {
    this._title = message;
    return this;
  }

  body(message) {
    this._body = message;
    return this;
  }

  button(text, iconPath) {
    this.buttons.push({ text, iconPath });
    return this;
  }

  async show(player) {
    const response = cloneResponse(takeResponse(player, "ActionFormData"));
    if (!response.canceled && response.selection !== undefined) {
      if (response.selection < 0 || response.selection >= this.buttons.length) {
        throw new Error(
          `[server-ui mock] Scripted selection ${response.selection} is out of range for ${this.buttons.length} button(s).`
        );
      }
    }
    return response;
  }
}

export class ModalFormData {
  constructor() {
    this._title = undefined;
    this.fields = [];
  }

  title(message) {
    this._title = message;
    return this;
  }

  slider(label, min, max, options = {}) {
    if (min > max) {
      throw new Error(`[server-ui mock] slider() min (${min}) must not exceed max (${max}).`);
    }
    const defaultValue = options.defaultValue;
    if (defaultValue !== undefined && (defaultValue < min || defaultValue > max)) {
      throw new Error(`[server-ui mock] slider() defaultValue ${defaultValue} is outside [${min}, ${max}].`);
    }
    this.fields.push({ kind: "slider", label, min, max, valueStep: options.valueStep ?? 1, defaultValue });
    return this;
  }

  /**
   * v2.0.0: server-ui 2.x signature — dropdown(label, items, {defaultValueIndex}).
   * The response's formValues entry for a dropdown is the chosen item index.
   */
  dropdown(label, items, options = {}) {
    const defaultValueIndex = options.defaultValueIndex ?? 0;
    if (!Number.isInteger(defaultValueIndex) || defaultValueIndex < 0 || defaultValueIndex >= items.length) {
      throw new Error(`[server-ui mock] dropdown() defaultValueIndex ${defaultValueIndex} is outside [0, ${items.length - 1}].`);
    }
    this.fields.push({ kind: "dropdown", label, items, defaultValueIndex });
    return this;
  }

  submitButton(label) {
    this._submitLabel = label;
    return this;
  }

  async show(player) {
    const response = cloneResponse(takeResponse(player, "ModalFormData"));
    if (!response.canceled) {
      // formValues are indexed by field position across ALL field kinds.
      this.fields.forEach((field, index) => {
        const value = response.formValues?.[index];
        if (value === undefined) return;
        if (field.kind === "dropdown") {
          if (!Number.isInteger(value) || value < 0 || value >= field.items.length) {
            throw new Error(`[server-ui mock] Scripted dropdown index ${value} is outside [0, ${field.items.length - 1}].`);
          }
          return;
        }
        if (value < field.min || value > field.max) {
          throw new Error(
            `[server-ui mock] Scripted value ${value} for "${JSON.stringify(field.label)}" is outside the slider's real range [${field.min}, ${field.max}] — a physical slider cannot produce this value.`
          );
        }
        const steps = (value - field.min) / field.valueStep;
        if (Math.abs(Math.round(steps) - steps) > 1e-9) {
          throw new Error(
            `[server-ui mock] Scripted value ${value} for "${JSON.stringify(field.label)}" does not land on the slider's step grid (step ${field.valueStep}).`
          );
        }
      });
    }
    return response;
  }
}

export class MessageFormData {
  constructor() {
    this._title = undefined;
    this._body = undefined;
    this._button1 = undefined;
    this._button2 = undefined;
  }

  title(message) {
    this._title = message;
    return this;
  }

  body(message) {
    this._body = message;
    return this;
  }

  button1(message) {
    this._button1 = message;
    return this;
  }

  button2(message) {
    this._button2 = message;
    return this;
  }

  async show(player) {
    const response = cloneResponse(takeResponse(player, "MessageFormData"));
    if (!response.canceled && response.selection !== undefined && response.selection !== 0 && response.selection !== 1) {
      throw new Error(`[server-ui mock] MessageFormData selection must be 0 or 1, got ${response.selection}.`);
    }
    return response;
  }
}
